<script setup>
import { computed, onUnmounted, ref } from 'vue'
import { onHide, onLoad } from '@dcloudio/uni-app'
import { use_app_store, make_operation_id } from '@/stores/store.js'
import { use_write_loading } from '@/composables/useWriteLoading.js'
import SecondaryPageFrame from '@/components/SecondaryPageFrame.vue'
import FlowPageHeader from '@/components/FlowPageHeader.vue'
import ConfirmDialog from '@/components/ConfirmDialog.vue'
import EventConfirmDialog from '@/components/EventConfirmDialog.vue'
import EventActionLoading from '@/components/EventActionLoading.vue'

const store = use_app_store(), frame = ref(null), match_id = ref(''), error = ref(''), modal = ref(''), navigating = ref(false)
const { is_loading, run_with_loading, cancel_loading } = use_write_loading()
onLoad(options => { match_id.value = String(options?.match_id || '') })
const match = computed(() => store.match_detail(match_id.value)), access_error = computed(() => !store.session.is_authenticated ? 'Your session has expired. Please sign in again.' : !match.value ? 'This match session is unavailable.' : match.value.status !== 'searching' ? `This match is now ${match.value.status}. Open its latest status from Home.` : '')
const go = async (url, replace = false) => { if (navigating.value || is_loading.value) return; navigating.value = true; try { await (replace ? frame.value.navigate_replace(url) : frame.value.navigate_forward(url)) } catch (cause) { error.value = cause.message } finally { navigating.value = false } }
const mutate = async status => { modal.value = ''; const result = await run_with_loading(() => store.transition_match(match_id.value, status)); if (result.reason === 'cancelled') return; if (!result.success) { error.value = result.message; return } await go(status === 'paused' ? `/pages/auto-match/paused?match_id=${encodeURIComponent(match_id.value)}` : '/pages/home/index', true) }
const boost = async () => {
  modal.value = ''
  if (store.coin_balance < 20) { error.value = 'Priority Match needs 20 coins. No coins were deducted.'; await go('/pages/coins/index'); return }
  const result = await run_with_loading(() => store.save_draft('coin_spend', match_id.value, { kind: 'priority_match', match_id: match_id.value, operation_id: make_operation_id('priority-match') }))
  if (result.reason === 'cancelled') return
  if (!result.success) { error.value = result.message; return }
  await go(`/pages/coins/processing?return_context_id=${encodeURIComponent(result.data)}`)
}
onHide(() => { modal.value = ''; navigating.value = false; cancel_loading() }); onUnmounted(cancel_loading)
</script>

<template><SecondaryPageFrame ref="frame" :scroll-locked="!!modal"><template #header><FlowPageHeader title="Auto Match" interaction="amSearching.goBack.click.1" :busy="is_loading || navigating" @back="modal = 'leave'" /><text v-if="error" class="flow-error" role="alert">{{ error }}</text></template><view class="flow-body"><template v-if="!access_error"><view class="match-orbit"><view class="match-orbit-dot" /></view><text class="flow-title search-title">Finding your match</text><text class="flow-copy search-copy">Looking for someone who shares your interests.</text><view class="flow-card"><view class="flow-status-line"><text>Queue position</text><text>{{ match.queue_position || 'Waiting for update' }}</text></view><view class="flow-status-line"><text>Estimated wait</text><text>{{ match.estimated_wait_seconds == null ? 'Waiting for update' : `${Math.ceil(match.estimated_wait_seconds / 60)} min` }}</text></view><view class="flow-status-line"><text>Priority</text><text>{{ match.priority_until > store.clock_ms ? 'Active' : 'Standard' }}</text></view></view><view class="flow-card"><text class="flow-label">Priority Match · 20 coins</text><text class="flow-copy">Move closer to the front for 15 minutes. Queue movement still comes from the matching service.</text><view class="flow-secondary" role="button" :aria-disabled="match.priority_until > store.clock_ms" data-interaction="amSearching.openBoost.click.1" @click="modal = 'boost'">{{ match.priority_until > store.clock_ms ? 'Priority active' : 'Use Priority Match' }}</view></view><view class="flow-chip-row"><view class="flow-chip" role="button" data-interaction="amSearching.openAmHelp.click.1" @click="modal = 'help'">How Auto Match works</view><view class="flow-chip" role="button" data-interaction="amSearching.openPrefs.click.1" @click="go('/pages/auto-match/preferences')">Preferences</view></view></template><view v-else class="flow-card" role="alert">{{ access_error }}</view></view><template #footer><view v-if="!access_error" class="flow-footer"><view class="flow-primary" role="button" :aria-disabled="is_loading || navigating" data-interaction="amSearching.pauseQueue.click.1" @click="mutate('paused')">Pause</view><view class="flow-danger" role="button" :aria-disabled="is_loading || navigating" data-interaction="amSearching.askLeave.click.1" @click="modal = 'leave'">Leave Pool</view></view><view v-else class="flow-footer"><view class="flow-secondary" role="button" @click="go('/pages/home/index', true)">Return Home</view></view></template><template #overlays><ConfirmDialog :visible="modal === 'leave'" title="Leave the matching pool?" message="This ends the current session. It will not restart when you return." confirm-label="Leave Pool" danger @cancel="modal = ''" @confirm="mutate('left')" /><ConfirmDialog :visible="modal === 'boost'" title="Use Priority Match?" :message="`Spend 20 coins for 15 minutes. Current balance: ${store.coin_balance}.`" confirm-label="Spend 20 Coins" @cancel="modal = ''" @confirm="boost" /><EventConfirmDialog :open="modal === 'help'" label="How Auto Match works" style="--event-dialog-bottom: var(--app-safe-bottom);" @close="modal = ''"><text class="event-dialog-title">How Auto Match works</text><text class="event-dialog-copy">Cimoa sends your saved preferences to the matching service. Queue position, availability and results are displayed only from verified service events. Chat unlocks only after both students accept.</text><view class="event-dialog-secondary" role="button" @click="modal = ''">Close</view></EventConfirmDialog><EventActionLoading :visible="is_loading" :label="modal === 'boost' ? 'Activating Priority Match…' : 'Updating your match session…'" /></template></SecondaryPageFrame></template>

<style scoped>.match-orbit { position: relative; width: 183.206rpx; height: 183.206rpx; margin: 30.534rpx auto; border: 5.725rpx solid var(--cimoa-surface-card); border-radius: 50%; box-shadow: var(--cimoa-shadow-primary); }.match-orbit::before { content: ''; position: absolute; inset: 30.534rpx; border-radius: 50%; background: var(--cimoa-gradient-primary); }.match-orbit-dot { position: absolute; top: -9.542rpx; left: 76.336rpx; width: 26.718rpx; height: 26.718rpx; border-radius: 50%; background: var(--cimoa-brand-purple); animation: match-orbit 2.4s linear infinite; transform-origin: 15.267rpx 101.145rpx; }.search-title, .search-copy { text-align: center; } @keyframes match-orbit { to { transform: rotate(360deg); } }</style>
